async function api(path,opt={}){const o={method:opt.method||'GET',headers:{...opt.headers},credentials:'same-origin'};if(opt.data!==undefined){o.headers['Content-Type']='application/json';o.body=JSON.stringify(opt.data)}if(opt.body!==undefined)o.body=opt.body;if(o.method!=='GET'&&state.csrf)o.headers['X-CSRF-Token']=state.csrf;let r=await fetch('/api'+path,o),t=await r.json().catch(()=>({error:'Réponse invalide.'}));if(!r.ok){if(r.status===401&&state.me){state.me=null;renderAuth()}throw Error(window.AC_I18N&&state.language==='en'?(window.AC_I18N.en[t.error]||t.error||'Connection error.'):(t.error||'Erreur de connexion.'))}return t}
