function passwordField(label,name,attrs='required',placeholder=''){return tr`<div class="field"><label for="f-${E(name)}">${E(t(label))}</label><div class="password-row"><input id="f-${E(name)}" name="${E(name)}" type="password" ${attrs} ${placeholder?tr`placeholder="${E(t(placeholder))}"`:''}><button type="button" class="password-eye" data-action="toggle-password" data-target="f-${E(name)}" aria-controls="f-${E(name)}" aria-pressed="false" aria-label="${E(t('Afficher'))} ${E(t(label))}" title="${E(t('Afficher'))} ${E(t(label))}">${eyeIcon(false)}</button></div></div>`}
function passwordFeedback(){return '<p class="password-feedback" role="alert" aria-live="polite"></p>'}
function showPasswordFeedback(form,submit=false){const password=form.querySelector('input[name=password]'),confirmation=form.querySelector('input[name=password_confirm]');if(!password||!confirmation)return true;const p=password.value,c=confirmation.value;const message=(submit||p||c)?p.length!==6?'Le mot de passe doit contenir exactement 6 caractères.':(submit||c)&&p!==c?'Les mots de passe ne correspondent pas.':'':'';const output=form.querySelector('.password-feedback');if(output)output.textContent=t(message);password.setAttribute('aria-invalid',message==='Le mot de passe doit contenir exactement 6 caractères.'?'true':'false');confirmation.setAttribute('aria-invalid',message==='Les mots de passe ne correspondent pas.'?'true':'false');if(message&&submit){toast(t(message),true);(p.length!==6?password:confirmation).focus()}return !message}

function select(label,name,options,value='',attrs=''){return tr`<div class="field"><label for="f-${E(name)}">${E(t(label))}</label><select id="f-${E(name)}" name="${E(name)}" ${attrs}>${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return tr`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(['language','status','kind','audience','content_type'].includes(name)?t(l):l)}</option>`}).join('')}</select></div>`}
