function btn(label,action,klass='secondary',id='',extra=''){return tr`<button type="button" class="btn ${klass}" data-action="${action}" ${id!==''?tr`data-id="${E(id)}"`:''} ${extra}>${buttonText(label)}</button>`}
function empty(title='Rien à afficher',description='Les informations apparaîtront ici dès qu’elles seront disponibles.'){return tr`<div class="empty"><div class="empty-icon">${ic('layers')}</div><strong>${E(t(title))}</strong><p>${E(t(description))}</p></div>`}
function updateUnread(n){state.unread=Math.max(0,Number(n)||0);document.querySelectorAll('[data-unread-count]').forEach(el=>{if(state.unread)el.textContent=state.unread;else el.remove()});const navButton=document.querySelector('.nav-item[data-route="notifications"]'),headerButton=document.querySelector('.topbar button[data-route="notifications"]');if(state.unread){if(navButton&&!navButton.querySelector('[data-unread-count]'))navButton.insertAdjacentHTML('beforeend',tr`<span class="nav-count" data-unread-count>${state.unread}</span>`);if(headerButton&&!headerButton.querySelector('[data-unread-count]'))headerButton.insertAdjacentHTML('beforeend',tr`<span class="icon-count" data-unread-count>${state.unread}</span>`)}
 try{if(state.unread&&navigator.setAppBadge)navigator.setAppBadge(state.unread).catch(()=>{});else if(!state.unread&&navigator.clearAppBadge)navigator.clearAppBadge().catch(()=>{});navigator.serviceWorker?.controller?.postMessage({type:'AC_BADGE_COUNT',unread:state.unread})}catch{}
}
