function urlB64ToUint8(s){const pad='='.repeat((4-s.length%4)%4),binary=atob((s+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(binary,c=>c.charCodeAt(0))}
async function bindExistingPush(){if(!state.me||!window.isSecureContext||!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window)||Notification.permission!=='granted')return;try{const config=await api('/push/status');if(!config.configured||!config.enabled)return;const registration=await navigator.serviceWorker.ready,sub=await registration.pushManager.getSubscription();if(sub)await api('/push/subscriptions',{method:'POST',data:sub.toJSON()})}catch(e){console.warn('Abonnement push à vérifier :',e.message)}}
