// One router for menu buttons, cards, deep links and browser history. Never write location.hash
// from a popstate/hashchange: that would create a second history entry and undo Back.
let navigationToken=0,historyIndex=Number(window.history?.state?.acIndex)||0;
function resolveRoute(route){const key=String(route||'dashboard').replace(/^#/,'');const segment=/^users\/(students|teachers)$/.exec(key);const base=segment?'users':key;return nav.some(x=>x[0]===base&&visibleNav(x))?{key,base,view:segment?.[1]||'all'}:null}
function routeFromLocation(){return location.hash.slice(1)||'dashboard'}
function savePageState(key){const page=$('#page');if(!page||!key)return;state.scrollByRoute.set(key,window.scrollY||document.documentElement.scrollTop||0);const forms=[...page.querySelectorAll('form')].map(form=>[...form.elements].map(input=>{if(!input.name||['password','file','hidden','submit','button'].includes(input.type))return null;return input.type==='checkbox'||input.type==='radio'?{checked:input.checked}:{value:input.value}}));state.draftsByRoute.set(key,forms);if($('#filter'))state.filtersByRoute.set(key,$('#filter').value)}
function restorePageState(key){const saved=state.draftsByRoute.get(key);if(!saved)return;const page=$('#page');[...page.querySelectorAll('form')].forEach((form,i)=>[...form.elements].forEach((input,j)=>{const prev=saved[i]?.[j];if(!prev||!input.name||['password','file','hidden','submit','button'].includes(input.type))return;if('checked'in prev)input.checked=prev.checked;else input.value=prev.value}))}
async function goBack(){if(history.state?.acIndex>0&&history.state?.acFrom){history.back();return true}return navigate(state.previous&&resolveRoute(state.previous)?state.previous:'dashboard',{historyMode:'replace',direction:'back'})}
async function navigate(route,{reload=false,historyMode='push',direction='forward'}={}){
 if(!state.me)return false;const dest=resolveRoute(route);if(!dest)return false;const {key,base,view}=dest,old=state.routeKey||state.route,changed=old!==key,hadPage=!!$('#page'),token=++navigationToken;
 if(changed&&hadPage){savePageState(old);if(state.modal)closeModal()}
 if(changed)state.previous=old;state.route=base;state.routeKey=key;state.userView=view;state.menu=false;state.filter=state.filtersByRoute.get(key)||'';
 if(historyMode!=='none'&&(location.hash!=='#'+key||historyMode==='replace')){const prior=history.state?.acIndex??historyIndex;const next=historyMode==='replace'?prior:prior+1;historyIndex=next;history[historyMode==='replace'?'replaceState':'pushState']({acRoute:key,acIndex:next,acFrom:historyMode==='replace'&&history.state?.acFrom?history.state.acFrom:changed&&hadPage?old:history.state?.acFrom||null},'',location.pathname+location.search+'#'+key)}
 const sidebar=$('.sidebar-scroll'),scroll=sidebar?.scrollTop||0,main=$('.main'),mainScroll=main?.scrollTop||0;
 if(changed||!hadPage)shell();else{$('.sidebar')?.classList.remove('open');$('.mobile-overlay')?.classList.remove('show')}
 if(!changed&&!reload&&hadPage){if(view!=='all'&&base==='users')draw();return true}
 if(changed&&$('.sidebar-scroll'))$('.sidebar-scroll').scrollTop=scroll;
 try{await load(base);if(token!==navigationToken||state.routeKey!==key)return false;if(state.data.notifications?.unread!==undefined&&base==='notifications')updateUnread(state.data.notifications.unread);if(base==='dashboard'&&state.data.dashboard)updateUnread(state.data.dashboard.unread);draw();if(changed){if(direction==='back'||historyMode==='none'){restorePageState(key);window.scrollTo?.(0,state.scrollByRoute.get(key)||0)}else window.scrollTo?.(0,0);animatePage(direction)}else if(main)main.scrollTop=mainScroll;return true}
 catch(e){if(token!==navigationToken)return false;$('#page').innerHTML=heading('Information','Une erreur est survenue',e.message)+btn('Réessayer','retry');toast(e.message,true);return false}
}
function animatePage(direction){const page=$('#page');if(!page)return;page.classList.remove('page-enter-forward','page-enter-back');page.classList.add(direction==='back'?'page-enter-back':'page-enter-forward')}
function historyRoute(){if(!state.me){if(location.hash.startsWith('#reset/')){state.authTab='reset';renderAuth()}return}const key=routeFromLocation(),deep=/^notifications\/(\d+)$/.exec(key);if(deep){navigate('notifications',{historyMode:'none',direction:'back'}).then(ok=>{if(ok)action('open-notification',deep[1])});return}const dest=resolveRoute(key);if(!dest){navigate('dashboard',{historyMode:'replace',direction:'back'});return}if(dest.key!==state.routeKey){const back=Number(history.state?.acIndex)<historyIndex;historyIndex=Number(history.state?.acIndex)||0;navigate(dest.key,{historyMode:'none',direction:back?'back':'forward'})}}
