if(type==='document'){title='Déposer un document';html=tr`<form data-form="document">${field('Titre du document','title','text','','required')}${select('Catégorie','category',['Support de cours','Article scientifique','Mémoire','Thèse','Dictionnaire','Linguistique','Littérature','Didactique','Traduction','Méthodologie','Autre'])}<div class="form-grid">${field('Auteur','author')}${field('Année du document','document_year')}</div>${shareSelector()}<label class="check-row"><input type="checkbox" name="requires_ack" value="true"> Demander un accusé de lecture</label>${field('Fichier (PDF, image, texte, DOCX, XLSX — 10 Mo max)','file','file','','required accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx"')}<div class="form-actions"><button class="btn teal">Téléverser</button></div></form>`}
if(type==='result'){title='Saisir une note';let courseList=(state.data.courses?.items||[]).filter(x=>has('results.validate')||x.teacher_id===u.id);html=tr`<form data-form="result">${select('Cours','course_id',courseList.map(x=>[x.id,tr`${x.title} · ${x.level} · ${x.year_label}`]))}<div id="roster-field">${select('Étudiant','student_id',[[ '', 'Chargement des étudiants…' ]])}</div>${field('Note sur 20','score','number','','required min="0" max="20" step="0.01"')}<div class="muted-note">La note sera enregistrée comme brouillon et restera invisible pour l’étudiant jusqu’à validation et publication.</div><div class="form-actions"><button class="btn teal">Enregistrer la note</button></div></form>`}
