document.addEventListener('click',async e=>{let route=e.target.closest('[data-route]');if(route){e.preventDefault();return navigate(route.dataset.route)}const anchor=e.target.closest('a[href^="#"]');if(anchor&&resolveRoute(anchor.getAttribute('href'))){e.preventDefault();return navigate(anchor.getAttribute('href').slice(1))}let a=e.target.closest('[data-action]');if(a){if(a.classList.contains('modal-backdrop')&&e.target!==a)return;e.preventDefault();return action(a.dataset.action,a.dataset.id||'',a)}});
document.addEventListener('submit',e=>{let f=e.target.closest('form[data-form]');if(f){e.preventDefault();if(['register','password-change','reset','user-create'].includes(f.dataset.form)&&!showPasswordFeedback(f,true))return;if(!f.checkValidity()){f.reportValidity();return}let button=e.submitter;if(button){button.disabled=true;setTimeout(()=>button.disabled=false,1300)}submit(f,e)}});
async function loadRoster(){let selectCourse=$('#modal-root select[name=course_id]'),field=$('#roster-field');if(!field||!selectCourse)return;let id=selectCourse.value;if(!id){field.innerHTML='<div class="muted-note">Aucun cours attribué. Contactez le département.</div>';return}try{let d=await api('/courses/'+id+'/students');field.innerHTML=select('Étudiant','student_id',d.items.length?d.items.map(x=>[x.id,x.name+' · '+x.identifier]):[['','Aucun étudiant inscrit']]);}catch(e){field.innerHTML=tr`<div class="muted-note">${E(e.message)}</div>`}}
document.addEventListener('change',e=>{if(e.target.id==='official-pdf'){const label=$('#official-pdf-name');if(label)label.textContent=e.target.files?.[0]?.name||'Aucun fichier sélectionné'}if(e.target.name==='root_track_id'&&e.target.closest('form[data-form=pathway-node]')){const parent=e.target.closest('form').querySelector('select[name=parent_id]'),nodes=(state.data.pathways?.nodes||[]).filter(n=>String(n.root_track_id)===e.target.value&&n.status==='active');if(parent)parent.innerHTML='<option value="">Parcours principal</option>'+nodes.map(n=>tr`<option value="${n.id}">${E(n.name)}</option>`).join('')}if(e.target.name==='root_track_id'&&e.target.closest('form[data-form=pathway-user]')){const root=(state.data.pathways?.roots||[]).find(r=>String(r.id)===e.target.value);const node=$('#pathway-node-select');if(node)node.innerHTML=pathwayChoices(root?.name||'')}if(e.target.name==='track'&&e.target.closest('form[data-form=register],form[data-form=user-edit],form[data-form=user-create]')){const holder=e.target.closest('form').querySelector('#pathway-node-select');if(holder)holder.innerHTML=pathwayChoices(e.target.value)}if(e.target.name==='level'&&e.target.closest('form[data-form=register],form[data-form=user-edit],form[data-form=user-create]')){const form=e.target.closest('form'),track=form.querySelector('[name=track]')?.value,node=form.querySelector('[name=node_id]');if(track&&node){const temp=document.createElement('div');temp.innerHTML=pathwayChoices(track,node.value);const fresh=temp.querySelector('[name=node_id]');if(fresh)node.replaceWith(fresh)}}if(e.target.name==='content_type'){const type=e.target.value,field=$('#publication-file-field'),body=e.target.closest('form')?.querySelector('[name=body]');if(type!=='voice'&&voiceRecorder)clearVoice();if(field)field.hidden=type==='text'||type==='voice';const voice=document.getElementById('voice-controls');if(voice)voice.hidden=type!=='voice';const classField=$('#pdf-class-field');if(classField)classField.hidden=!type.includes('pdf');if(body)body.required=type==='text'||type==='voice';const file=field?.querySelector('input[type=file]');if(file){file.required=type!=='text'&&type!=='voice';file.accept=type.includes('pdf')?'application/pdf,.pdf':type.includes('image')?'image/jpeg,image/png,image/webp':type.includes('video')?'video/mp4,video/webm':'image/jpeg,image/png,image/webp,video/mp4,video/webm';file.value='';$('#publication-preview').replaceChildren()}}if(e.target.name==='node_id'){const field=e.target.closest('form')?.querySelector('#pathway-breadcrumb'),selected=e.target.selectedOptions?.[0]?.textContent;if(field&&selected)field.textContent=selected}if(e.target.name==='media_file'){const f=e.target.files?.[0],preview=e.target.closest('form')?.querySelector('#publication-preview');if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);if(preview){preview.replaceChildren();if(f&&(f.type.startsWith('image/')||f.type.startsWith('video/'))){state.previewUrl=URL.createObjectURL(f);const node=document.createElement(f.type.startsWith('image/')?'img':'video');node.className='publication-media';node.src=state.previewUrl;if(node.tagName==='VIDEO')node.controls=true;preview.append(node)}else if(f&&f.type==='application/pdf')preview.textContent=f.name+' · '+(f.size/1024/1024).toFixed(2)+' Mo';else if(f)preview.textContent='Format de fichier non pris en charge.'}}});
document.addEventListener('change',e=>{if(e.target.name==='level'&&e.target.closest('form[data-form=register]')){const sel=document.querySelector('form[data-form=register] select[name=track]'),cycle=e.target.value.startsWith('Licence')?'Licence':e.target.value.startsWith('Master')?'Master':'Doctorat';if(sel)sel.innerHTML='<option value="">Non précisé</option>'+(state.meta.tracks||[]).filter(t=>JSON.parse(t.levels_json||'[]').includes(cycle)).map(t=>tr`<option value="${E(t.name)}">${E(t.name)}</option>`).join('');const holder=e.target.closest('form')?.querySelector('#pathway-node-select');if(holder)holder.innerHTML=pathwayChoices('')}if(e.target.id==='font-px'&&$('#font-preview')){$('#font-preview').style.fontSize=e.target.value+'px';let custom=document.querySelector('form[data-form=font] input[name=custom_px]');if(custom)custom.value=''}if(e.target.id==='result-view-status'||e.target.id==='result-view-sort')$('#result-view-rows').innerHTML=resultViewRows();if(e.target.id==='view-status'||e.target.id==='view-sort')$('#view-rows').innerHTML=viewRows();if(e.target.name==='pathway_filter'){state.pathwayRootFilter=e.target.value;draw()}if(e.target.id==='tracking-scope'){state.trackingScope=e.target.value;draw()}if(e.target.matches('select[name=course_id]'))loadRoster();if(e.target.matches('select[name=kind]')){let extra=$('#student-extra');if(extra)extra.style.display=e.target.value==='etudiant'?'contents':'none'}});
