document.addEventListener('input',e=>{if(e.target.name==='custom_px'&&e.target.closest('form[data-form=font]')){let px=Number(e.target.value||$('#font-px')?.value||16);if(px>=14&&px<=24){$('#font-preview').style.fontSize=px+'px'}}if(e.target.id==='result-view-search'){$('#result-view-rows').innerHTML=resultViewRows()}if(e.target.id==='view-search'){let pos=e.target.selectionStart;$('#view-rows').innerHTML=viewRows();e.target.focus();e.target.setSelectionRange(pos,pos)}if(e.target.id==='tracking-search'){state.trackingFilter=e.target.value;let pos=e.target.selectionStart;draw();let input=$('#tracking-search');input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.id==='pathway-search'){state.pathwayFilter=e.target.value;const pos=e.target.selectionStart;draw();const input=$('#pathway-search');input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.id==='teacher-search'){state.teacherFilter=e.target.value;const pos=e.target.selectionStart;draw();const input=$('#teacher-search');input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.id==='filter'){state.filter=e.target.value;state.filtersByRoute.set(state.routeKey,e.target.value);let pos=e.target.selectionStart;draw();let input=$('#filter');input?.focus();input?.setSelectionRange(pos,pos)}});
function portalMatches(user){const isChef=user?.roles?.some(r=>r.name==='chef');if(isChef!==chiefPortal){location.replace((isChef?'/chef':'/')+location.hash);return false}return true}
async function openInitialRoute(){const hash=routeFromLocation(),match=/^notifications\/(\d+)$/.exec(hash),dest=resolveRoute(match?'notifications':hash);await navigate(dest?.key||'dashboard',{historyMode:'replace'});syncUnread();if(match)await action('open-notification',match[1]);}
// Respect native system edge gestures. This is an optional in-app gesture, never a replacement for the back button.
let swipeStart=null;
function swipeExcluded(target){return !!target?.closest('input,textarea,select,button,a,video,audio,canvas,[contenteditable],.modal,.sidebar,.mobile-overlay,[data-no-swipe],.table-wrap,.filters,.search-input,.tracking-meter')}
function hasUnsubmittedForm(){return [...document.querySelectorAll('form')].some(form=>[...form.elements].some(el=>{if(!el.name||el.disabled||['hidden','submit','button'].includes(el.type))return false;if(el.type==='checkbox'||el.type==='radio')return el.checked!==el.defaultChecked;if(el.tagName==='SELECT'){const index=[...el.options].findIndex(o=>o.defaultSelected);return el.selectedIndex!==(index<0?0:index)}return el.value!==(el.defaultValue??'')}))}
function versionCompare(a,b){const x=String(a||'').split('.').map(Number),y=String(b||'').split('.').map(Number);if(x.length!==3||y.length!==3||[...x,...y].some(n=>!Number.isSafeInteger(n)))return 0;for(let i=0;i<3;i++)if(x[i]!==y[i])return x[i]-y[i];return 0}
function renderUpdateBanner(){let box=document.getElementById('ac-update-banner');const info=state.updateInfo,release=info?.release,build=window.AC_BUILD_VERSION;if(!release||versionCompare(release.version,build)<=0){box?.remove();document.body.classList.remove('update-visible');return}const dismissed=Number(sessionStorage.getItem('ac-update-dismissed-'+release.version)||0),duration=release.mandatory?10*60000:6*3600000;if(Date.now()-dismissed<duration){box?.remove();document.body.classList.remove('update-visible');return}document.body.classList.add('update-visible');if(!box){box=document.createElement('aside');box.id='ac-update-banner';box.className='update-banner';box.setAttribute('role','status');document.body.appendChild(box)}box.innerHTML=tr`<img src="${OFFICIAL_LOGO}" alt="" width="75" height="36"><div class="update-copy"><strong>${E(release.title)} · ${E(release.version)}</strong><span>Nouvelle mise à jour disponible ! ${release.mandatory?t('Mise à jour obligatoire :')+' '+E(release.reason):t('Appuyez sur Mettre à jour pour profiter des nouveautés.')}</span><details><summary>Nouveautés de la mise à jour</summary>${release.features.length?tr`<b>Nouveautés</b><ul>${release.features.map(x=>tr`<li>${E(x)}</li>`).join('')}</ul>`:''}${release.fixes.length?tr`<b>Corrections et améliorations</b><ul>${release.fixes.map(x=>tr`<li>${E(x)}</li>`).join('')}</ul>`:''}</details></div><div class="update-actions"><button type="button" data-action="apply-update" class="btn teal">Mettre à jour</button><button type="button" data-action="dismiss-update" class="btn secondary small" aria-label="Fermer temporairement">Plus tard</button></div>`}
async function checkAppVersion(){try{state.updateInfo=await api('/app-version');renderUpdateBanner()}catch{/* Offline: do not fabricate an update. */}}
async function applyWebUpdate(){const release=state.updateInfo?.release;if(!release||versionCompare(release.version,window.AC_BUILD_VERSION)<=0)return renderUpdateBanner();if(hasUnsubmittedForm()){toast('Enregistrez ou annulez votre formulaire avant de mettre à jour. Votre saisie est conservée.',true);return}const button=document.querySelector('#ac-update-banner [data-action=apply-update]');if(button){button.disabled=true;button.textContent='Préparation…'}try{sessionStorage.setItem('ac-updated-target',release.version);if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.getRegistration('/');if(reg){await reg.update();let waiting=reg.waiting;if(!waiting&&reg.installing){waiting=reg.installing;await Promise.race([new Promise(resolve=>{if(waiting.state==='installed')resolve();else waiting.addEventListener('statechange',()=>{if(waiting.state==='installed'||waiting.state==='activated')resolve()})}),new Promise(resolve=>setTimeout(resolve,12000))]);waiting=reg.waiting}if(waiting){if(navigator.serviceWorker.controller){navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});waiting.postMessage({type:'AC_SKIP_WAITING'});setTimeout(()=>location.reload(),12000);return}waiting.postMessage({type:'AC_SKIP_WAITING'})}}}location.reload()}catch(e){if(button){button.disabled=false;button.textContent='Mettre à jour'}toast('Mise à jour indisponible : '+e.message,true)}}
document.addEventListener('touchstart',e=>{swipeStart=null;if(e.touches.length!==1||state.modal||!state.me||state.route==='dashboard'||swipeExcluded(e.target))return;const x=e.touches[0].clientX;if(x<28||x>Math.min(105,window.innerWidth*.23))return;if(hasUnsubmittedForm())return;swipeStart={x,y:e.touches[0].clientY,at:Date.now(),route:state.route}} ,{passive:true});
document.addEventListener('touchend',e=>{const start=swipeStart;swipeStart=null;if(!start||e.changedTouches.length!==1||state.modal||state.route!==start.route||swipeExcluded(e.target)||hasUnsubmittedForm())return;const dx=e.changedTouches[0].clientX-start.x,dy=e.changedTouches[0].clientY-start.y;if(dx<100||Math.abs(dy)>45||dx<Math.abs(dy)*2.5||Date.now()-start.at>900)return;goBack()},{passive:true});
document.addEventListener('touchcancel',()=>{swipeStart=null},{passive:true});
window.addEventListener('popstate',historyRoute);window.addEventListener('hashchange',historyRoute);
(async()=>{try{state.meta=await api('/meta');let m=await api('/me');state.me=m.user;state.csrf=m.csrf;if(state.me){if(!portalMatches(state.me))return;try{state.data.display=await api('/display');state.language=state.data.display.language||'fr';document.documentElement.lang=state.language;applyTextSize(state.data.display.font_px)}catch{}await openInitialRoute();bindExistingPush()}else if(m.pending)waitForApproval(m.csrf);else renderAuth()}catch(e){$('#app').innerHTML=tr`<div class="empty"><strong>Connexion au serveur impossible</strong><p>${E(e.message)}</p></div>`}})();

document.addEventListener('error',e=>{const media=e.target;if(!media?.matches?.('.publication-media,.publication-audio'))return;const parent=media.parentElement;if(!parent||parent.querySelector('.publication-media-error'))return;const note=document.createElement('p');note.className='publication-media-error';note.setAttribute('role','alert');note.textContent='Fichier indisponible. Réessayez ou contactez le département.';media.after(note) },true);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(state.pending)checkApproval();if(state.me)syncUnread()}});

